import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const i="/assets/logo.DKjuK0cp.png",n="/assets/ram_guide_mmc.CElJg6TU.png",l="/assets/ram_guide_vanilla_1.HSr3RF1a.png",s="/assets/ram_guide_vanilla_2.BbRQ2xnR.png",u="/assets/ram_guide_vanilla_3.BNz-Xa34.png",d="/assets/gpu_guide.CI-o3h5J.png",h="/assets/folderinafolder.DyTH3k1r.png",c="/assets/chunk_multidraw.HZWK3Apk.png",p="/assets/latest_log.C2gG5TTJ.png",m="/assets/javacheck.BU_XZYWK.png",x=JSON.parse('{"title":"Setup","description":"","frontmatter":{},"headers":[],"relativePath":"install/faq.md","filePath":"install/faq.md","lastUpdated":1788364293000}'),f={name:"install/faq.md"};function g(y,e,b,k,w,v){return a(),o("div",null,[...e[0]||(e[0]=[r('<div style="text-align:center;"><img src="'+i+'" alt="Logo" width="200" style="display:block;margin:0 auto;"></div><p>Check the table of contents on the right, or just Ctrl-F, to search through this document.</p><p>Credit to Ataraxia for writing the original version of this document.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>💬 Having issues? Feel free to ask in our <a href="https://discord.mcsrranked.com" target="_blank" rel="noreferrer">Discord server</a> in the <code>#public-help</code> channel.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>&quot;MCSR&quot; stands for &quot;<strong>M</strong>ine<strong>c</strong>raft <strong>S</strong>peed<strong>r</strong>unning&quot;, <strong><u>not</u></strong> for &quot;Minecraft Speedrunning Ranked&quot;. The mod is called &quot;MCSR Ranked&quot;, or &quot;Ranked&quot; for short.</p></div><h1 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h1><h2 id="info" tabindex="-1">Where can I find information about Ranked? <a class="header-anchor" href="#info" aria-label="Permalink to &quot;Where can I find information about Ranked? {#info}&quot;">​</a></h2><ul><li>Website: <a href="https://mcsrranked.com/" target="_blank" rel="noreferrer">https://mcsrranked.com/</a></li><li>Discord: <a href="https://discord.mcsrranked.com/" target="_blank" rel="noreferrer">https://discord.mcsrranked.com/</a></li></ul><h2 id="setup-setup" tabindex="-1">How do I set up Ranked? <a class="header-anchor" href="#setup-setup" aria-label="Permalink to &quot;How do I set up Ranked? {#setup-setup}&quot;">​</a></h2><p>See <a href="https://mcsrranked.com/download" target="_blank" rel="noreferrer">the download page</a> or <a href="./index">the installation guide</a> for your launcher for instructions.</p><ul><li>Since most speedrunners run on Minecraft 1.16.1, this mod is developed for 1.16.1. It will not work in other versions of Minecraft.</li></ul><h2 id="new" tabindex="-1">I am new. How do I get into speedrunning? <a class="header-anchor" href="#new" aria-label="Permalink to &quot;I am new. How do I get into speedrunning? {#new}&quot;">​</a></h2><p>Follow <a href="https://youtu.be/l-q-_4R8_6M" target="_blank" rel="noreferrer">this video</a> for a tutorial to set up Minecraft for speedrunning. It goes through everything from setting up Prism Launcher to installing mods and practice maps, so it&#39;s highly recommended to watch this first. It mainly focuses on Windows; see <a href="#linux">here for Linux</a> and <a href="#macos">here for macOS</a> for more setup resources.</p><p>The most important things to learn when starting out are bastion routes and one-cycling. Watch <a href="https://www.youtube.com/playlist?list=PL7Q35RXRsOR-udeKzwlYGJd0ZrvGJ0fwu" target="_blank" rel="noreferrer">these videos</a> for introductory bastion routes and <a href="https://youtu.be/JaVyuTyDxxs" target="_blank" rel="noreferrer">this video</a> for one-cycling.</p><p>In general, it&#39;s a good idea to watch top runs and top runners&#39; streams to get a feel of how a speedrun goes. Here&#39;s a <a href="https://www.youtube.com/playlist?list=PLwJbTWLH-1dakBZaROfNJZ-m59OQg_hFp" target="_blank" rel="noreferrer">more comprehensive playlist</a> and a <a href="https://metafy.gg/guides/view/ultimate-minecraft-speedrun-guide-cIzfjeTmwOm" target="_blank" rel="noreferrer">full comprehensive guide</a>, but since they cover a lot of strategies it may seem overwhelming at first, so take it easy.</p><h2 id="my-game-fails-to-launch-or-crashes-while-playing" tabindex="-1">My game fails to launch or crashes while playing <a class="header-anchor" href="#my-game-fails-to-launch-or-crashes-while-playing" aria-label="Permalink to &quot;My game fails to launch or crashes while playing&quot;">​</a></h2><p>See <a href="#crashes">Crashes</a> for a guide on troubleshooting a crash.</p><h2 id="update-java" tabindex="-1">How do I update my Java version? <a class="header-anchor" href="#update-java" aria-label="Permalink to &quot;How do I update my Java version? {#update-java}&quot;">​</a></h2><p>Using Java 17+ is highly recommended for multiple reasons, such as performance and compatibility with some practice mods and MCSR Ranked features. At the time of writing this, downloading replays and Discord RPC require using a newer Java version.</p><ul><li>for Prism Launcher or MultiMC: follow <a href="./install_prism#updating-java">this guide</a></li><li>for Modrinth App: follow <a href="./install_modrinth#updating-java">this guide</a></li><li>for official launcher: follow <a href="./install_vanilla#advanced-update-java">this guide</a></li></ul><h2 id="failauth" tabindex="-1">When I launch the game, I get a &quot;Player authentication data couldn&#39;t be loaded from Minecraft Auth API&quot; error <a class="header-anchor" href="#failauth" aria-label="Permalink to &quot;When I launch the game, I get a &quot;Player authentication data couldn&#39;t be loaded from Minecraft Auth API&quot; error {#failauth}&quot;">​</a></h2><p>If you&#39;re on Prism/MultiMC:</p><ul><li>Close the game. In the launcher, select your account name (top-right of launcher), click &quot;Manage accounts&quot;, right-click your account and select &quot;Refresh&quot;.</li></ul><p>If you&#39;re on another launcher:</p><ul><li>Close the game and try restarting your launcher. If you still get the same error, sign out and sign in to the launcher.</li></ul><p>If you&#39;re on a cracked launcher:</p><ul><li>You need a <a href="https://www.minecraft.net/" target="_blank" rel="noreferrer">Minecraft account</a> to play Ranked, since Ranked requires your player UUID.</li></ul><p>If the above don&#39;t work, try <a href="https://wiki.mcsrranked.com/install/faq#update-java" target="_blank" rel="noreferrer">updating Java</a>.</p><h2 id="failed-to-connect" tabindex="-1">When I hover over the ranked button, I get &quot;Failed to connect to server :(&quot; <a class="header-anchor" href="#failed-to-connect" aria-label="Permalink to &quot;When I hover over the ranked button, I get &quot;Failed to connect to server :\\(&quot; {#failed-to-connect}&quot;">​</a></h2><ul><li>If you are from Russia, this is almost definitely due to internet censorship. People have reported that adding mcsrranked.com to zapret&#39;s lists/list-general.txt has fixed their issue.</li><li>Else, check if the Ranked server is down (check #maintenances in the Discord server).</li><li>If it isn&#39;t down, check that the version of your Ranked mod matches the latest release. <a href="#find-minecraft">Navigate to your mods folder</a> and check the version number of the <code>mcsrranked</code> mod, comparing it to the <a href="https://modrinth.com/mod/mcsr-ranked/version/latest" target="_blank" rel="noreferrer">latest version</a>. If they don&#39;t match, replace your outdated mod with the latest version.</li><li>Lastly, something on your end (network, firewall, antivirus, etc.) might be blocking the ranked mod from working. See <a href="#network">network issues</a> for potential fixes.</li></ul><h2 id="find-minecraft" tabindex="-1">Where do I find my .minecraft folder / mods folder? <a class="header-anchor" href="#find-minecraft" aria-label="Permalink to &quot;Where do I find my .minecraft folder / mods folder? {#find-minecraft}&quot;">​</a></h2><p>If you&#39;re on Prism:</p><ul><li>Select your instance and click &quot;Folder&quot;. Navigate to <code>minecraft/</code> or to <code>minecraft/mods/</code>.</li></ul><p>If you&#39;re on MultiMC:</p><ul><li>Select your instance and click &quot;Minecraft Folder&quot; to open your .minecraft folder, or &quot;View Mods&quot; to view your mods.</li></ul><p>If you&#39;re on the default launcher (Windows):</p><ul><li>Hold the Windows key and press R. Type in <code>%appdata%</code> and press Enter, then go into <code>.minecraft</code>. The <code>mods</code> folder is located within <code>.minecraft</code>.</li></ul><p>If you&#39;re on the default launcher (macOS):</p><ul><li>Go to <code>/Library/Application Support/minecraft</code>. <ul><li>If you can&#39;t find this folder, enable <a href="https://nordlocker.com/blog/how-to-show-hidden-files-mac/" target="_blank" rel="noreferrer">Show hidden files</a>.</li></ul></li></ul><h2 id="gamma" tabindex="-1">How do I increase my brightness/gamma? <a class="header-anchor" href="#gamma" aria-label="Permalink to &quot;How do I increase my brightness/gamma? {#gamma}&quot;">​</a></h2><p>It is legal to set gamma to up to 5.0.</p><p>If you&#39;re using the latest version of Speedrunning Sodium, you can adjust the brightness level up to 500% in-game via <code>Options</code> &gt; <code>Video Settings</code> from the title screen, <u>not</u> in the world.</p><p>Otherwise, go to your <a href="#find-minecraft">.minecraft folder</a>, open options.txt and change the value next to gamma to 5.0, or follow <a href="#setup-setup">the setup guide</a> for a guide on setting up mods.</p><h2 id="allocate-ram" tabindex="-1">How do I allocate more RAM to Minecraft? <a class="header-anchor" href="#allocate-ram" aria-label="Permalink to &quot;How do I allocate more RAM to Minecraft? {#allocate-ram}&quot;">​</a></h2><p>If you&#39;re on Prism or MultiMC:</p><ul><li>Go to Settings &gt; Java and set the maximum memory allocation to somewhere around 3000.</li></ul><div style="text-align:center;"><img src="'+n+'" alt="ram_guide_mmc.png" style="display:block;margin:0 auto;"></div><p>If you&#39;re on the default launcher (though the default RAM allocation is fine):</p><ol><li>Go to Installations, find the installation you&#39;re using and click the &quot;...&quot; button. Click &quot;Edit&quot;.</li></ol><div style="text-align:center;"><img src="'+l+'" alt="ram_guide_vanilla_1.png" style="display:block;margin:0 auto;"></div><ol><li>Click &quot;More Options&quot;, then adjust the number after -Xmx. <ul><li>You can change &quot;G&quot; to &quot;M&quot; to edit in terms of MB instead of GB.</li></ul></li></ol><div style="text-align:center;"><img src="'+s+'" alt="ram_guide_vanilla_2.png" style="display:block;margin:0 auto;"><br><img src="'+u+'" alt="ram_guide_vanilla_3.png" style="display:block;margin:0 auto;"></div><p>Do not allocate too much RAM since <a href="https://vazkii.net/blog_archive/%22%20%5Cl%20%22blog/ram-explanation" target="_blank" rel="noreferrer">it may cause lag spikes</a>.</p><h2 id="use-dgpu" tabindex="-1">How do I get Minecraft to use my high-performance GPU? <a class="header-anchor" href="#use-dgpu" aria-label="Permalink to &quot;How do I get Minecraft to use my high-performance GPU? {#use-dgpu}&quot;">​</a></h2><p>On Windows:</p><ol><li>For Windows 10, press the Start button and type &quot;Graphics settings&quot;. Under Graphics performance preference, click &quot;Browse&quot;. For Windows 11, under Graphics performance preference, click &quot;Add desktop app.&quot;</li></ol><div style="text-align:center;"><img src="'+d+'" alt="gpu_guide.png" style="display:block;margin:0 auto;"></div><ol start="2"><li>Select the javaw.exe that Minecraft is using, and set it to &quot;High performance&quot;.</li></ol><p>If you don&#39;t know where to find javaw.exe,</p><p>If you&#39;re on Prism/MultiMC:</p><ul><li>Go to Edit (instance) &gt; Settings &gt; Java, and copy the path in &quot;Java path&quot;.</li></ul><p>If you&#39;re on the default launcher:</p><ul><li>Go to Installations, find the installation you&#39;re using and click the &quot;...&quot; button. Click &quot;Edit&quot;, then &quot;More Options&quot;. Copy the path in &quot;Java executable&quot;.</li></ul><p>Alternatively, you can follow steps 1-5 of <a href="https://obsproject.com/kb/minecraft-java-edition-troubleshooting" target="_blank" rel="noreferrer">this guide</a>.</p><h2 id="performance" tabindex="-1">I have worse performance than expected <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;I have worse performance than expected {#performance}&quot;">​</a></h2><p>This is usually caused by one or more of the following issues:</p><ul><li><a href="#allocate-ram">Not allocating enough RAM</a></li><li><a href="#update-java">Using Java 8 instead of 17+</a></li><li><a href="#use-dgpu">Using the integrated GPU</a> (if you have multiple GPUs) for the Java version you&#39;re using</li></ul><h2 id="elo-command" tabindex="-1">How do I add custom commands like <code>!elo</code> on Twitch? <a class="header-anchor" href="#elo-command" aria-label="Permalink to &quot;How do I add custom commands like `!elo` on Twitch? {#elo-command}&quot;">​</a></h2><p>OshBot has some commands for Ranked like <code>+elo</code>, see <a href="https://bot.osh.gay/ranked/elo" target="_blank" rel="noreferrer">its documentation</a>.</p><p>Additionally, there are some commands for Fossabot / Nightbot:</p><ul><li>(Fossabot) <code>!today</code> (replace MC_USERNAME with your minecraft username) - made by memerson</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$(eval r=$(customapi https://mcsr-stats.memerson.xyz/api/matches?timeframe=$(urlencode $(uptime))&amp;username=MC_USERNAME); r[&#39;error&#39;] ? `${r[&#39;error&#39;]}` : `$(channel.display_name)&#39;s stats since stream start - Elo: ${r[&#39;totalEloChange&#39;]} | Record: ${r[&#39;wonMatchesCount&#39;]} W - ${r[&#39;lossMatchesCount&#39;]} L - ${r[&#39;drawCount&#39;]} D`)</span></span></code></pre></div><ul><li>(Fossabot) <code>!elo</code> (change BROADCASTER_MC_IGN to your Minecraft in-game name) – made by Neal</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$(eval r=$(customapi &lt;https://mcsrranked.com/api/users/$(index1&gt; BROADCASTER_MC_IGN)); \\`stats for ${r\\[&#39;data&#39;\\]\\[&#39;nickname&#39;\\]} - elo: ${r\\[&#39;data&#39;\\]\\[&#39;elo_rate&#39;\\]} | rank: ${r\\[&#39;data&#39;\\]\\[&#39;elo_rank&#39;\\]} | record: ${r\\[&#39;data&#39;\\]\\[&#39;records&#39;\\]\\[&#39;2&#39;\\]\\[&#39;win&#39;\\]} W - ${r\\[&#39;data&#39;\\]\\[&#39;records&#39;\\]\\[&#39;2&#39;\\]\\[&#39;lose&#39;\\]} L\\`) | full leaderboard: &lt;https://mcsrranked.com/leaderboard&gt;</span></span></code></pre></div><ul><li>(Nightbot) <code>!elo</code> (requires <code>!elohelper</code>, change BROADCASTER_MC_IGN to your Minecraft in-game name) – made by Neal</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\\-a=!elohelper $(eval \\`$(1)\\` == \\`null\\` ? \\`BROADCASTER_MC_IGN\\` : \\`$(1)\\`)</span></span></code></pre></div><ul><li>(Nightbot) <code>!elohelper</code> – made by Neal</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$(eval r=$(urlfetch json &lt;https://mcsrranked.com/api/users/$(1)&gt;); \\`stats for ${r\\[&#39;data&#39;\\]\\[&#39;nickname&#39;\\]} - elo: ${r\\[&#39;data&#39;\\]\\[&#39;elo_rate&#39;\\]} | rank: ${r\\[&#39;data&#39;\\]\\[&#39;elo_rank&#39;\\]} | record: ${r\\[&#39;data&#39;\\]\\[&#39;records&#39;\\]\\[&#39;2&#39;\\]\\[&#39;win&#39;\\]} W - ${r\\[&#39;data&#39;\\]\\[&#39;records&#39;\\]\\[&#39;2&#39;\\]\\[&#39;lose&#39;\\]} L\\`)</span></span></code></pre></div><h2 id="linux" tabindex="-1">I am on Linux. How do I set everything up? <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;I am on Linux. How do I set everything up? {#linux}&quot;">​</a></h2><p>See <a href="https://its-saanvi.github.io/linux-mcsr" target="_blank" rel="noreferrer">here</a> for a guide to setup Minecraft for speedrunning on Linux.</p><p>Use <a href="https://github.com/tesselslate/resetti" target="_blank" rel="noreferrer">resetti</a> for window resizing on X11.</p><p>Use <a href="https://tesselslate.github.io/waywall" target="_blank" rel="noreferrer">waywall</a> for window resizing on Wayland + many useful features.</p><p>You can join the MCSR Linux Discord server <a href="https://discord.gg/CVxuagAXMt" target="_blank" rel="noreferrer">here</a>.</p><h2 id="macos" tabindex="-1">I am on macOS. How do I set everything up? <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;I am on macOS. How do I set everything up? {#macos}&quot;">​</a></h2><p>To set up speedrunning on Mac, follow <a href="https://www.youtube.com/watch?v=sRSR55A7VCE" target="_blank" rel="noreferrer">the macOS setup guide</a>.</p><p>Use <a href="https://github.com/Slackow/SlackowWall/releases/latest" target="_blank" rel="noreferrer">SlackowWall</a> for resizing Minecraft.</p><p>Follow <a href="https://youtu.be/RmAmL7JhGJw" target="_blank" rel="noreferrer">this guide</a> to set up boateye.</p><p>You can join the Mac speedrunning Discord server <a href="https://discord.gg/sczfsdE39W" target="_blank" rel="noreferrer">here</a>.</p><h2 id="is-there-a-discord-server-for-discords" tabindex="-1">Is there a Discord server for ...? (#discords) <a class="header-anchor" href="#is-there-a-discord-server-for-discords" aria-label="Permalink to &quot;Is there a Discord server for ...? (#discords)&quot;">​</a></h2><p>You can find a spreadsheet of MCSR Discord servers <a href="https://docs.google.com/spreadsheets/d/1W5D6sxqBfIdyxS1pVEAi2ZaFhOhj4x-9bZwD39HbgLo" target="_blank" rel="noreferrer">here</a>.</p><h1 id="gameplay-issues" tabindex="-1">Gameplay issues <a class="header-anchor" href="#gameplay-issues" aria-label="Permalink to &quot;Gameplay issues&quot;">​</a></h1><h2 id="standardsettings" tabindex="-1">My settings reset whenever I join a new world / Minecraft exits fullscreen whenever I join a new world <a class="header-anchor" href="#standardsettings" aria-label="Permalink to &quot;My settings reset whenever I join a new world / Minecraft exits fullscreen whenever I join a new world {#standardsettings}&quot;">​</a></h2><p>StandardSettings is a mod that resets your settings to specified values whenever you join a new world. You can find instructions on how to configure it <a href="https://github.com/contariaa/StandardSettings" target="_blank" rel="noreferrer">here</a>. If you don&#39;t want your settings to reset, remove this mod from your mods folder.</p><h2 id="entity-culling" tabindex="-1">Entity counter (E counter) stays at -1 / blockEntities doesn&#39;t appear when doing mapless or preemptive navigation <a class="header-anchor" href="#entity-culling" aria-label="Permalink to &quot;Entity counter (E counter) stays at -1 / blockEntities doesn&#39;t appear when doing mapless or preemptive navigation {#entity-culling}&quot;">​</a></h2><p>Go to Options &gt; Video Settings and toggle Entity Culling off.</p><h2 id="entity-distance" tabindex="-1">E-ray can&#39;t find far bastions <a class="header-anchor" href="#entity-distance" aria-label="Permalink to &quot;E-ray can&#39;t find far bastions {#entity-distance}&quot;">​</a></h2><p>Go to Options &gt; Video Settings and set your Entity Distance to 500%.</p><h2 id="lazychunks" tabindex="-1">Decreasing the render distance by 1 doesn&#39;t unload the spawner <a class="header-anchor" href="#lazychunks" aria-label="Permalink to &quot;Decreasing the render distance by 1 doesn&#39;t unload the spawner {#lazychunks}&quot;">​</a></h2><p>Spawners up to 3 chunks outside your render distance remain loaded and will still show up on the pie chart. This is why just dropping your render distance by 1 won&#39;t unload the spawner. You have to drop it by at least 4 to unload it.</p><p><em>Example: If the spawner loads in at 15 chunks, you should decrease your render distance to 11 (press Shift-F3-F four times), then increase it to 14 (press F3-F three times). Reopen the pie chart and the spawner should be gone.</em></p><h2 id="ghostbucket" tabindex="-1">My buckets are glitchy / didn&#39;t pick up/place water <a class="header-anchor" href="#ghostbucket" aria-label="Permalink to &quot;My buckets are glitchy / didn&#39;t pick up/place water {#ghostbucket}&quot;">​</a></h2><p>Ghost buckets occur if your crosshair moves from one block to another as you right click with a bucket. Keep your mouse still while you right click to prevent them from occurring.</p><h2 id="folderinafolder" tabindex="-1">Practice maps don&#39;t show up in the list of worlds <a class="header-anchor" href="#folderinafolder" aria-label="Permalink to &quot;Practice maps don&#39;t show up in the list of worlds {#folderinafolder}&quot;">​</a></h2><p>Make sure your folder structure is correct:</p><div style="text-align:center;"><img src="'+h+'" alt="folderinafolder.png" style="display:block;margin:0 auto;"></div><h2 id="multidraw" tabindex="-1">Water is invisible / block textures don&#39;t display properly <a class="header-anchor" href="#multidraw" aria-label="Permalink to &quot;Water is invisible / block textures don&#39;t display properly {#multidraw}&quot;">​</a></h2><p>E.g.:</p><div style="text-align:center;"><img src="'+c+'" alt="chunk_multidraw.png" style="display:block;margin:0 auto;"></div><p>In the title screen, go to Options &gt; Click the Book &amp; Quill (top right) &gt; Sodium and disable &quot;Use Chunk Multi-Draw&quot;.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Chunk Multidraw is a Sodium option that boosts performance. On a small percentage of GPUs, it will cause this issue, so you will have to disable it if you&#39;re having this issue.</p></div><h2 id="rd-cap-16" tabindex="-1">I can&#39;t increase my render distance beyond 16 (or some other number) <a class="header-anchor" href="#rd-cap-16" aria-label="Permalink to &quot;I can&#39;t increase my render distance beyond 16 (or some other number) {#rd-cap-16}&quot;">​</a></h2><p><a href="#allocate-ram">Allocate more RAM</a>.</p><h2 id="ghost-nether" tabindex="-1">Blocks don&#39;t drop / entities are frozen <a class="header-anchor" href="#ghost-nether" aria-label="Permalink to &quot;Blocks don&#39;t drop / entities are frozen {#ghost-nether}&quot;">​</a></h2><p>(also referred to as an &quot;internal server crash&quot;; it&#39;s in this section because the game doesn&#39;t force quit like most crashes)</p><p>This is known as a ghost nether or phantom nether. Once you get this, if it isn&#39;t just Minecraft lagging a lot, there&#39;s nothing you can do about it, since you&#39;ve basically crashed (so you&#39;ll need to restart Minecraft).</p><p>You can help us determine the cause of this issue. If you experience this, paste your <a href="#crashes">log file</a> in #bug-report in the <a href="https://discord.mcsrranked.com/" target="_blank" rel="noreferrer">Ranked discord server</a>.</p><h2 id="jarfix" tabindex="-1">Ninjabrain Bot appears like a zip file, double-clicking it doesn&#39;t run it <a class="header-anchor" href="#jarfix" aria-label="Permalink to &quot;Ninjabrain Bot appears like a zip file, double-clicking it doesn&#39;t run it {#jarfix}&quot;">​</a></h2><p>If you&#39;re having issues with .jar programs on Windows, download and run <strong>Jarfix.exe</strong> from <a href="https://github.com/qMaxXen/Jarfix/releases/latest" target="_blank" rel="noreferrer">this page</a>.</p><h2 id="mpkdebug" tabindex="-1">MiniPracticeKit doesn&#39;t work <a class="header-anchor" href="#mpkdebug" aria-label="Permalink to &quot;MiniPracticeKit doesn&#39;t work {#mpkdebug}&quot;">​</a></h2><p>To troubleshoot MiniPracticeKit not working, please verify the following:</p><ul><li>A file that&#39;s at least 20 KB named <strong>exactly</strong> &quot;hotbar&quot; or &quot;hotbar.nbt&quot;, <u>not</u> &quot;hotbar (1).nbt&quot; or similar, exists in your .minecraft folder.</li><li>You are pressing your <strong>Hotbar slot 1</strong> hotkey while holding your <strong>Load hotbar</strong> hotkey, and both of these aren&#39;t conflicting with other hotkeys.</li></ul><h2 id="fnlock" tabindex="-1">I can&#39;t press F3 without holding Fn / some F3 keys don&#39;t work <a class="header-anchor" href="#fnlock" aria-label="Permalink to &quot;I can&#39;t press F3 without holding Fn / some F3 keys don&#39;t work {#fnlock}&quot;">​</a></h2><p>Toggle Fn-lock on your pc <a href="https://www.thewindowsclub.com/how-to-lock-and-unlock-function-fn-key-in-windows" target="_blank" rel="noreferrer">https://www.thewindowsclub.com/how-to-lock-and-unlock-function-fn-key-in-windows</a>. If you&#39;re on a Lenovo, the setting is in Lenovo Vantage &gt; Device &gt; Input &amp; Accessories &gt; Select F1-F12 function.</p><p>If you don&#39;t have an F3 key at all, which means you need to press Fn-3 to use F3, see <a href="#rebind">this section</a> for a tutorial on how to rebind a key to F3.</p><h2 id="rebind" tabindex="-1">How can I rebind my F3 key or other keys that aren&#39;t possible to rebind in Minecraft? <a class="header-anchor" href="#rebind" aria-label="Permalink to &quot;How can I rebind my F3 key or other keys that aren&#39;t possible to rebind in Minecraft? {#rebind}&quot;">​</a></h2><ul><li>To rebind keys on Windows, <a href="https://www.youtube.com/watch?v=YqS-fxPx_jo" target="_blank" rel="noreferrer">install Toolscreen</a></li><li>In Toolscreen, navigate to Advanced ➔ Inputs ➔ Keyboard ➔ Open Keyboard Layout</li><li>Rebind keys by right-clicking. A more detailed rebind tutorial is available <a href="https://youtu.be/LG13ljK9RPs?t=486" target="_blank" rel="noreferrer">here</a> (timestamped)</li></ul><p>If you are on Mac or Linux, see <a href="#macos">#macos</a> or <a href="#linux">#linux</a> for other resources.</p><h3 id="rebind-rules" tabindex="-1">Rebind Rules <a class="header-anchor" href="#rebind-rules" aria-label="Permalink to &quot;Rebind Rules {#rebind-rules}&quot;">​</a></h3><p>You may remap keys using external programs, but:</p><ul><li>Each game input may have only one key, and each key may cause only one game input</li><li>F3 shortcuts (such as F3+C, Shift+F3, etc.) can&#39;t be bound to a single button</li><li>Inputs must be buttons - no scrolling the scroll-wheel or similar</li><li>Rebinding &quot;Attack/Destroy&quot; or &quot;Use Item/Place Block&quot; to a keyboard button in order to abuse as an autoclicker is not allowed</li></ul><h2 id="narrator" tabindex="-1">How can I disable the narrator? <a class="header-anchor" href="#narrator" aria-label="Permalink to &quot;How can I disable the narrator? {#narrator}&quot;">​</a></h2><p>Go to the Ranked main menu ⟶ <strong>Settings</strong> and set &quot;Narrator Hotkey&quot; to <strong>OFF</strong>.</p><h2 id="srigt-settings" tabindex="-1">How do I access the timer settings? <a class="header-anchor" href="#srigt-settings" aria-label="Permalink to &quot;How do I access the timer settings? {#srigt-settings}&quot;">​</a></h2><p>Go to Options -&gt; click the Book &amp; Quill (top right) -&gt; SpeedRunIGT.</p><h2 id="singleplayer" tabindex="-1">Can I practice seeds filtered with this mod? <a class="header-anchor" href="#singleplayer" aria-label="Permalink to &quot;Can I practice seeds filtered with this mod? {#singleplayer}&quot;">​</a></h2><p>You can practice by playing in matches (ranked, casual, or private rooms), or by recreating worlds saved to singleplayer (i.e. seeds you have played in previous matches).</p><p>Playing by yourself in private rooms is possible only with a <a href="https://mcsrranked.com/store" target="_blank" rel="noreferrer">paid supporter tier</a> or with an alt account.</p><p><a href="https://modrinth.com/mod/fsg-mod" target="_blank" rel="noreferrer">FSG mod</a> is a different mod with different filters that allows you to play filtered seeds.</p><h2 id="nether-bonking" tabindex="-1">I was teleported immediately after entering the nether (and took some fall damage / can&#39;t find my nether portal) <a class="header-anchor" href="#nether-bonking" aria-label="Permalink to &quot;I was teleported immediately after entering the nether (and took some fall damage / can&#39;t find my nether portal) {#nether-bonking}&quot;">​</a></h2><p>You were likely nether-bonked. This is when the game forgets to divide your coordinates by 8 when putting you in the nether from the overworld. It&#39;s caused by going through a nether portal while left-clicking, so don&#39;t hold down left-click at the time the portal animation finishes.</p><h1 id="crashes" tabindex="-1">Crashes <a class="header-anchor" href="#crashes" aria-label="Permalink to &quot;Crashes {#crashes}&quot;">​</a></h1><p>If Minecraft crashes, you should paste your log to the <a href="https://maskers.xyz/log-analysis/" target="_blank" rel="noreferrer">log analyzer website</a>. If the response you get isn&#39;t helpful, or you need further help, please describe your issue and send the same log in the #public-help channel in the <a href="https://discord.mcsrranked.com/" target="_blank" rel="noreferrer">Ranked discord server</a>.</p><ul><li>If you&#39;re on Prism or MultiMC, a console window will open when the game crashes. Click &quot;Upload&quot; to upload the log to a mclo.gs/pastee.dev link, then copy the link and send it. It will contain both latest.log and the crash report, as well as more additional information:</li></ul><div style="text-align:center;"><img src="https://i.imgur.com/MfrJwcM.png" alt="mmclog.png" width="500" style="display:block;margin:0 auto;"></div><ul><li>If you&#39;re on a different launcher, <a href="#find-minecraft">go to your .minecraft folder</a> &gt; logs and select latest.log. Send this file:</li></ul><div style="text-align:center;"><img src="'+p+'" alt="latest_log.png" width="500" style="display:block;margin:0 auto;"></div><ul><li>The crash report can sometimes be found in .minecraft/crash-reports, with the date of the crash in its file name. It contains a little more information about the crash itself, but the log file is usually sufficient to diagnose issues.</li><li>If there&#39;s an error message, sending a screenshot of that would be helpful too, in case there isn&#39;t a crash report generated.</li></ul><p>The following sections will go through some issues. &quot;Symptoms&quot; means things to look for if you&#39;re not sure what crash it is. This is mostly included for those who may be interested; it&#39;s not meant to be extensive, and the above is a way better way to diagnose a crash.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><p>Exit codes in log files are never sufficient to diagnose the problem. If you get a crash, please <a href="#crashes">send the full log</a> when asking for help and not just the exitcode.</p><h2 id="outdated-java-version" tabindex="-1">Outdated Java version <a class="header-anchor" href="#outdated-java-version" aria-label="Permalink to &quot;Outdated Java version&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;Java is version 1.8&quot; under &quot;Checking Java version…&quot;</li><li>&quot;- java 8&quot; under &quot;Loading mods&quot;</li><li>&quot;UnsupportedClassVersionError&quot; followed by &quot;has been compiled by a more recent version of the Java Runtime&quot;</li></ul><p>Explanation:</p><ul><li>Old versions of some mods and some practice mods require newer versions of Java than the version bundled with the game.</li></ul><p>Fix:</p><ul><li>Update Java by following the steps linked <a href="#update-java">here</a>.</li></ul><h2 id="_32-bit-java" tabindex="-1">32-bit Java <a class="header-anchor" href="#_32-bit-java" aria-label="Permalink to &quot;32-bit Java&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;Error occurred during initialization of VM&quot; followed by &quot;Could not reserve enough space for [memory allocated] object heap&quot;</li></ul><p>Explanation:</p><ul><li>You can&#39;t allocate RAM above a certain amount if you use 32-bit Java.</li></ul><p>Fix:</p><ul><li><a href="#update-java">Update Java to a 64-bit version</a>.</li></ul><h2 id="javacheck-jar-on-default-launcher-and-prism-launcher" tabindex="-1">JavaCheck.jar (on default launcher and Prism Launcher) <a class="header-anchor" href="#javacheck-jar-on-default-launcher-and-prism-launcher" aria-label="Permalink to &quot;JavaCheck.jar (on default launcher and Prism Launcher)&quot;">​</a></h2><p>Symptoms:</p><ul><li>In the default launcher: Error message mentioning &quot;Your Java Runtime is incompatible. Please edit your installation to use the bundled Java Runtime. Name: Java version mismatch&quot;</li></ul><div style="text-align:center;"><img src="'+m+'" alt="javacheck.png" width="500" style="display:block;margin:0 auto;"></div><ul><li>In Prism launcher: &quot;This instance is not compatible with Java version…&quot;</li></ul><p>Explanation:</p><ul><li>Minecraft doesn&#39;t like it when you change your Java version.</li></ul><p>Fix (default launcher):</p><ul><li>Watch <a href="https://youtu.be/HEtqR74M-_w" target="_blank" rel="noreferrer">this video</a>. Read the pinned comment if you&#39;re on the Windows store version of the launcher. You&#39;ll have to do this every time the launcher updates.</li></ul><p>Fix (Prism Launcher):</p><ul><li>Go to Edit &gt; Settings &gt; Java &gt; enable Skip Java compatibility checks.</li></ul><h2 id="incompatible-mods-outdated-mods-or-mods-with-dependencies" tabindex="-1">Incompatible mods, outdated mods, or mods with dependencies <a class="header-anchor" href="#incompatible-mods-outdated-mods-or-mods-with-dependencies" aria-label="Permalink to &quot;Incompatible mods, outdated mods, or mods with dependencies&quot;">​</a></h2><p>Symptoms:</p><ul><li>Error message mentioning &quot;Incompatible mod set found!&quot;, followed by a list of mods stating they are &quot;not whitelisted&quot;</li></ul><p>Explanation:</p><ul><li>The ranked mod is only compatible with specific whitelisted mods to prevent cheating, and only specific versions of these mods are whitelisted. See the <a href="https://mc.sr/mods" target="_blank" rel="noreferrer">list of allowed mods</a> for more details.</li></ul><p>Fix:</p><ul><li>Refer to the error message; it will tell you which mods are not whitelisted and whether a different version of a mod you&#39;re using is whitelisted. Remove the mods that are not whitelisted and <a href="https://mc.sr/mods/" target="_blank" rel="noreferrer">update</a> the mods that the error message tells you to update.</li><li>If you are still confused, it&#39;s possible that some mods just recently got updated and haven&#39;t been updated yet. Feel free to send a screenshot of the error message in #public-help for help.</li></ul><h2 id="too-little-ram-allocated-usually-only-on-multimc" tabindex="-1">Too little RAM allocated (usually only on MultiMC) <a class="header-anchor" href="#too-little-ram-allocated-usually-only-on-multimc" aria-label="Permalink to &quot;Too little RAM allocated (usually only on MultiMC)&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;OutOfMemoryError: Java heap space&quot; (This error may also indicate a memory leak. Check your RAM allocation to determine which is more likely.)</li></ul><p>Symptoms in the crash report:</p><ul><li>In &quot;Memory&quot; under &quot;System Details&quot;, there are three numbers in brackets. If the latter two are &quot;1024 MB&quot; or any number less than 1900 MB*, you may have this issue. <ul><li>*If you are using Shenandoah GC and know what you are doing, having a lower memory allocation is fine, as long as it&#39;s not too low (&lt;1200 MB)</li></ul></li></ul><p>Explanation:</p><ul><li>By default, MultiMC allocates 1024 MB of RAM to Minecraft. This was sufficient for Minecraft versions before 1.13, but for anything after that, 1024 MB is too low. It should be set to somewhere from 2000 MB to 3000 MB, <a href="https://vazkii.net/blog_archive/%22%20%5Cl%20%22blog/ram-explanation" target="_blank" rel="noreferrer">but not too high</a>. You only really need a high RAM allocation (2800-3000) if you play on 32 render distance (possibly because you&#39;re speedrunning All Advancements).</li></ul><p>Fix:</p><ul><li><a href="#allocate-ram">Allocate more RAM to Minecraft</a>.</li></ul><h2 id="onedrive-usually-only-on-multimc" tabindex="-1">OneDrive (usually only on MultiMC) <a class="header-anchor" href="#onedrive-usually-only-on-multimc" aria-label="Permalink to &quot;OneDrive (usually only on MultiMC)&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;OneDrive&quot; mentioned basically anywhere</li></ul><p>Explanation:</p><ul><li>This occurs when your launcher folder is located in OneDrive while OneDrive is enabled. OneDrive can mess with your game files to save space, and this can to issues.</li></ul><p>Fix:</p><ul><li>Move your launcher folder outside OneDrive, for example to &quot;C:/MultiMC&quot;. If you want to unlink OneDrive, follow <a href="https://support.microsoft.com/en-au/office/turn-off-disable-or-uninstall-onedrive-f32a17ce-3336-40fe-9c38-6efb09f944b0" target="_blank" rel="noreferrer">this link</a>.</li></ul><h2 id="memory-leak-occurs-more-frequently-for-macos-users" tabindex="-1">Memory leak (occurs more frequently for macOS users) <a class="header-anchor" href="#memory-leak-occurs-more-frequently-for-macos-users" aria-label="Permalink to &quot;Memory leak (occurs more frequently for macOS users)&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;OutOfMemoryError&quot; (This error may also be caused by allocating too little RAM. Check your RAM allocation to determine which is more likely.)</li><li>&quot;There is insufficient memory for the Java Runtime Environment to continue&quot;</li></ul><p>Other symptoms:</p><ul><li>Minecraft using abnormally high RAM before the crash (check your task manager)</li></ul><p>Explanation:</p><ul><li>Memory leaks occur when memory which is no longer needed is not released. Most commonly (in 1.16.1), the newest version of Sodium has a memory leak on macOS.</li></ul><p>Fix:</p><ul><li>Assuming the memory leak is caused by Sodium, replace Sodium with a version downloaded from <a href="https://mc.sr/mods/" target="_blank" rel="noreferrer">this website</a> after selecting Mac.</li></ul><h2 id="resizing-the-window-to-a-large-height" tabindex="-1">Resizing the window to a large height <a class="header-anchor" href="#resizing-the-window-to-a-large-height" aria-label="Permalink to &quot;Resizing the window to a large height&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;java.lang.RuntimeException: GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT&quot;</li></ul><p>Explanation:</p><ul><li>Depending on your hardware, resizing the Minecraft window past a certain height will make it crash.</li></ul><p>Fix:</p><ul><li>If you&#39;re using Jingle for it, reduce the height in Jingle -&gt; Scripts -&gt; Resizing.</li></ul><h2 id="jvm-crash" tabindex="-1">JVM crash <a class="header-anchor" href="#jvm-crash" aria-label="Permalink to &quot;JVM crash&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;A fatal error has been detected by the Java Runtime Environment&quot; followed by &quot;EXCEPTION_ACCESS_VIOLATION&quot;</li><li>&quot;.minecraft\\hs_err_pid&lt;id&gt;.log&quot;, where &lt;id&gt; is a few numbers</li></ul><p>Other symptoms:</p><ul><li>A separate log file named hs_err_pid&lt;id&gt;.log (where &lt;id&gt; is a few numbers) appears in your .minecraft folder. This file technically has more information about the crash but no one can read it.</li></ul><p>Explanation and fix: this crash may be caused by one of the following –</p><ul><li>Concurrently running programs, such as OBS and Discord, that use the same graphics card as the game. <ul><li>Try using window capture instead of game capture in OBS.</li><li>Try disabling hardware acceleration in Discord.</li><li>If you&#39;re on a laptop, <a href="#use-dgpu">make sure</a> Minecraft is using the dedicated GPU if you have one.</li></ul></li><li>A compatibility issue between SpeedrunIGT, Intel Graphics and OpenGL. Enable &quot;safe font mode&quot; in SpeedrunIGT options. If the game crashes before you can access that menu, delete .minecraft/speedrunigt.</li><li>Driver issues. Check if your drivers are updated, and update them or downgrade them if they&#39;re already updated.</li></ul><p>Generally, JVM crashes are difficult to diagnose, so there&#39;s not much we can help with if it isn&#39;t caused by one of the above issues.</p><h2 id="concurrentmodificationexception-cme" tabindex="-1">ConcurrentModificationException (CME) <a class="header-anchor" href="#concurrentmodificationexception-cme" aria-label="Permalink to &quot;ConcurrentModificationException (CME)&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;ConcurrentModificationException&quot;, optionally accompanied with &quot;Exception loading structure&quot; or &quot;StructureManager&quot;</li></ul><p>Explanation:</p><ul><li>CMEs are rare crashes that are basically caused by RNG. There is a fix for a specific CME in StructureManager in Java 11+ (see below), which crashes with &quot;Exception loading structure&quot; or with a mention of &quot;StructureManager&quot;.</li></ul><p>Fix:</p><ul><li>Add <a href="https://github.com/modmuss50/Voyager/releases/tag/1.0.0" target="_blank" rel="noreferrer">Voyager</a> to your mods folder (you should do this regardless of whether you experienced this crash, so that future crashes may be prevented).</li></ul><h2 id="network" tabindex="-1">Network issues <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network issues {#network}&quot;">​</a></h2><p>Symptoms in the log file:</p><ul><li>&quot;UnknownHostException: No such host is known (mcsrranked.com)&quot;</li><li>&quot;java.net.SocketTimeoutException: Connect timed out&quot;</li></ul><p>Explanation:</p><ul><li>Something on your end (network, firewall, antivirus, etc.) is blocking the Ranked mod from working.</li></ul><p>Fix:</p><ul><li>If you are from Russia, this is almost definitely due to internet censorship. People have reported that adding mcsrranked.com to zapret&#39;s lists/list-general.txt has fixed their issue.</li><li>Try again later.</li><li>Check if your firewall/antivirus is blocking mcsrranked.com.</li><li>Try <a href="https://developers.google.com/speed/public-dns/docs/using%22%20%5Cl%20%22windows" target="_blank" rel="noreferrer">changing your DNS provider</a>.</li><li>Try using a VPN/proxy.</li><li>Try rebooting your PC.</li><li>Try rebooting your router.</li><li><a href="https://test-ipv6.com/" target="_blank" rel="noreferrer">Make sure ipv6 works fine</a>, if not, <a href="https://www.google.com/search?q=how+to+disable+ipv6+on+windows" target="_blank" rel="noreferrer">try disabling it</a>.</li><li>On Windows, run these 3 commands in cmd launched as admin: <code>ipconfig /flushdns</code>, <code>netsh interface ip reset</code>, <code>netsh winsock reset</code>; and reboot afterwards.</li><li>Try using a different network.</li></ul>',236)])])}const _=t(f,[["render",g]]);export{x as __pageData,_ as default};
